// @ai-proposed SHOP-142 — generated by the verify-feature skill.
// Verifies: AC-1, AC-2, AC-3, AC-5 (see verification/SHOP-142/VERIFICATION_PLAN.md)
import { test, expect } from '@playwright/test';

async function openCart(page) {
  await page.goto('/');
  await expect(page.getByTestId('subtotal')).toHaveText('$120.00');
}

async function applyCode(page, code) {
  await page.getByLabel('Discount code').fill(code);
  await page.getByRole('button', { name: 'Apply' }).click();
}

async function expectNoSidewaysScroll(page) {
  const overflow = await page.evaluate(
    () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
  );
  expect(overflow).toBeLessThanOrEqual(0);
}

test('SHOP-142 AC-1 the cart has a discount code field and Apply button', async ({ page }) => {
  await openCart(page);
  const input = page.getByLabel('Discount code');
  await expect(input).toBeVisible();
  await expect(input).toBeEditable();
  await expect(page.getByRole('button', { name: 'Apply' })).toBeVisible();
  await input.fill('SAVE10');
  await expect(input).toHaveValue('SAVE10');
});

test('SHOP-142 AC-2 SAVE10 shows the discount line and total $108.00; FLAT20 then replaces it', async ({ page }) => {
  await openCart(page);
  await applyCode(page, 'SAVE10');
  await expect(page.getByText('Discount (SAVE10)')).toBeVisible();
  await expect(page.getByTestId('discount')).toHaveText('−$12.00');
  await expect(page.getByTestId('total')).toHaveText('$108.00');

  await applyCode(page, 'FLAT20');
  await expect(page.getByText('Discount (FLAT20)')).toBeVisible();
  await expect(page.getByText('Discount (SAVE10)')).toHaveCount(0);
  await expect(page.getByTestId('discount')).toHaveText('−$20.00');
  await expect(page.getByTestId('total')).toHaveText('$100.00');
});

test('SHOP-142 AC-3 an empty code shows "Enter a discount code." and the total stays $120.00', async ({ page }) => {
  await openCart(page);
  await applyCode(page, '');
  await expect(page.getByRole('alert')).toHaveText('Enter a discount code.');
  await expect(page.getByTestId('total')).toHaveText('$120.00');
});

test('SHOP-142 AC-3 an unknown code shows "That code is not valid." and the total stays $120.00', async ({ page }) => {
  await openCart(page);
  await applyCode(page, 'NOPE99');
  await expect(page.getByRole('alert')).toHaveText('That code is not valid.');
  await expect(page.getByTestId('discount')).toHaveCount(0);
  await expect(page.getByTestId('total')).toHaveText('$120.00');
});

test('SHOP-142 AC-3 a bad code after SAVE10 shows the error and removes the discount', async ({ page }) => {
  await openCart(page);
  await applyCode(page, 'SAVE10');
  await expect(page.getByTestId('total')).toHaveText('$108.00');
  await applyCode(page, 'NOPE99');
  await expect(page.getByRole('alert')).toHaveText('That code is not valid.');
  await expect(page.getByTestId('discount')).toHaveCount(0);
  await expect(page.getByTestId('total')).toHaveText('$120.00');
});

test('SHOP-142 AC-5 on a Pixel 7 SAVE10 gives total $108.00 with no sideways scrolling', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'mobile', 'Phone check runs in the mobile project only');
  await openCart(page);
  await applyCode(page, 'SAVE10');
  await expect(page.getByTestId('total')).toHaveText('$108.00');
  await expectNoSidewaysScroll(page);
});

test('SHOP-142 AC-5 on a Pixel 7 an unknown code shows the error with no sideways scrolling', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'mobile', 'Phone check runs in the mobile project only');
  await openCart(page);
  await applyCode(page, 'NOPE99');
  await expect(page.getByRole('alert')).toHaveText('That code is not valid.');
  await expect(page.getByTestId('total')).toHaveText('$120.00');
  await expectNoSidewaysScroll(page);
});
